import type { HomeTaskKind, HomeTaskTone } from "./home.types";

export function greetingFor(date: Date): string {
  const hour = date.getHours();
  if (hour < 12) return "Good morning";
  if (hour < 18) return "Good afternoon";
  return "Good evening";
}

const DZD = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });

export function formatDzd(amount: number): string {
  return `${DZD.format(Math.round(amount))} DZD`;
}

export function partnerImageSrc(image: string | null): string | null {
  if (!image) return null;
  if (image.startsWith("data:") || image.startsWith("http") || image.startsWith("//")) {
    return image;
  }
  return `data:image/jpeg;base64,${image}`;
}

export function composeAddress(
  street: string | null,
  street2: string | null,
  zip: string | null,
): string {
  return [street, street2, zip]
    .map((part) => (part ?? "").trim())
    .filter(Boolean)
    .join(", ");
}

export function formatDistance(meters: number): string {
  if (meters < 1000) return `${Math.round(meters)} m`;
  return `${(meters / 1000).toFixed(1)} km`;
}

export function haversineMeters(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const earth = 6371000;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 2 * earth * Math.asin(Math.sqrt(h));
}

const COLLECT = /(collect|cash|recouvre|paiement|payment|encaiss)/i;
const DELIVERY = /(deliver|livrais|picking|ship|confirm)/i;
const SURVEY = /(survey|audit|sondage|availab|enqu)/i;

export function classifyTask(name: string): {
  kind: HomeTaskKind;
  tone: HomeTaskTone;
} {
  if (COLLECT.test(name)) return { kind: "collect", tone: "amber" };
  if (DELIVERY.test(name)) return { kind: "delivery", tone: "blue" };
  if (SURVEY.test(name)) return { kind: "survey", tone: "violet" };
  return { kind: "task", tone: "slate" };
}
