<template>
  <F7Popup v-bind="$attrs" :opened="opened" @popup:closed="$emit('update:opened', false)">
    <F7Page>
      <F7Navbar title="Server Configuration">
        <F7NavRight>
          <F7Link popup-close>Close</F7Link>
        </F7NavRight>
      </F7Navbar>
      <F7Block>
        <F7List>
          <F7ListInput
            label="Server URL"
            type="url"
            placeholder="https://example.presalio.com"
            :value="form.address"
            @input="form.address = $event.target.value"
            clear-button
          >
          </F7ListInput>
          <F7ListInput
            label="Server Name"
            type="text"
            placeholder="My Server"
            :value="form.name"
            @input="form.name = $event.target.value"
            clear-button
          >
          </F7ListInput>
          <F7ListInput
            label="Default DB"
            type="text"
            placeholder="Database"
            :value="form.database"
            @input="form.database = $event.target.value"
            clear-button
          >
          </F7ListInput>
        </F7List>
        <div class="padding">
          <F7Button fill large @click="save">Save & Select</F7Button>
        </div>

        <F7BlockTitle>Saved Servers</F7BlockTitle>
        <F7List>
          <F7ListItem
            v-for="server in servers"
            :key="server.id"
            :title="server.name"
            :subtitle="server.address"
            :after="server.id === currentServerId ? 'Active' : ''"
            @click="select(server.id)"
          >
            <template #swipeout-actions-right>
              <F7SwipeoutButton delete @click="remove(server.id)">Delete</F7SwipeoutButton>
            </template>
          </F7ListItem>
        </F7List>
      </F7Block>
    </F7Page>
  </F7Popup>
</template>

<script setup lang="ts">
import { reactive, computed } from "vue";
import { useServerStore } from "@/shared/stores/server.store";

const props = defineProps<{ opened: boolean }>();
const emit = defineEmits<{ (e: "update:opened", val: boolean): void }>();

const serverStore = useServerStore();
const servers = computed(() => serverStore.servers);
const currentServerId = computed(() => serverStore.currentServerId);

const form = reactive({
  name: "Default",
  address: "",
  database: "",
});

const save = async () => {
  if (!form.address) return;

  // Simple add for now
  await serverStore.addServer({
    name: form.name,
    address: form.address,
    database: form.database,
  });

  // Reset form
  form.name = "Default";
  form.address = "";
  form.database = "";

  emit("update:opened", false);
};

const select = async (id: string) => {
  await serverStore.selectServer(id);
  emit("update:opened", false);
};

const remove = async (id: string) => {
  await serverStore.removeServer(id);
};
</script>
