<template>
  <div
    class="flex items-center gap-3 rounded-2xl border border-[rgba(222,230,244,0.7)] bg-[rgba(255,255,255,0.72)] p-3 shadow-[0_8px_18px_rgba(39,66,112,0.05)]"
  >
    <span :class="['flex h-10 w-10 shrink-0 items-center justify-center rounded-xl', iconClass]">
      <ILucideBanknote v-if="task.kind === 'collect'" class="h-[18px] w-[18px]" />
      <ILucideTruck v-else-if="task.kind === 'delivery'" class="h-[18px] w-[18px]" />
      <ILucideClipboardList v-else-if="task.kind === 'survey'" class="h-[18px] w-[18px]" />
      <ILucideListChecks v-else class="h-[18px] w-[18px]" />
    </span>

    <div class="min-w-0 flex-1">
      <p class="truncate text-[14px] font-[700] leading-tight text-[#10162c]">
        {{ task.title }}
      </p>
      <p v-if="task.partnerName" class="mt-0.5 truncate text-[12px] text-[#657096]">
        {{ task.partnerName }}
      </p>
    </div>

    <span v-if="task.detail" :class="['shrink-0 text-[12px] font-[760]', detailClass]">
      {{ task.detail }}
    </span>
  </div>
</template>

<script setup lang="ts">
import type { HomePendingTask } from "../home.types";

const props = defineProps<{
  task: HomePendingTask;
}>();

const ICON_TONE: Record<string, string> = {
  amber: "text-[#d97706] bg-[#f59e0b]/12",
  blue: "text-[#1f6df5] bg-[#1f6df5]/10",
  violet: "text-[var(--f7-theme-color)] bg-[rgba(139,42,243,0.1)]",
  slate: "text-[#566285] bg-[#566285]/10",
};

const DETAIL_TONE: Record<string, string> = {
  amber: "text-[#d97706]",
  blue: "text-[#1f6df5]",
  violet: "text-[var(--f7-theme-color)]",
  slate: "text-[#657096]",
};

const iconClass = computed(() => ICON_TONE[props.task.tone]);
const detailClass = computed(() => DETAIL_TONE[props.task.tone]);
</script>
